class ListNode:
    def __init__(self, val=0, next=None):
        self.val, self.next = val, next

def reverse(head):
    prev, curr = None, head
    while curr:
        nxt = curr.next                # save it before overwriting the link
        curr.next = prev               # point this node backward
        prev, curr = curr, nxt
    return prev                        # the old tail is the new head

def middle(head):
    slow = fast = head
    while fast and fast.next:          # fast moves 2 steps, slow moves 1
        slow, fast = slow.next, fast.next.next
    return slow                        # the second middle if the length is even

def merge(a, b):
    dummy = tail = ListNode()          # dummy head: the first node is not a special case
    while a and b:
        if a.val <= b.val:
            tail.next, a = a, a.next
        else:
            tail.next, b = b, b.next
        tail = tail.next
    tail.next = a or b                 # attach whatever is left
    return dummy.next
